-- An identity column draws from its own sequence, and the clause over it is refused as
-- already an identity column — not as a column that has a default.
-- @expect-error: already an identity column (55000)
-- @expect-message
-- @setup
CREATE TABLE aid (c INT GENERATED BY DEFAULT AS IDENTITY, v TEXT);
-- @test
ALTER TABLE aid ALTER COLUMN c ADD GENERATED ALWAYS AS IDENTITY;
